174: vec3 tonemap_agx(vec3 color) {
175: 	// Input color should be non-negative!
176: 	// Large negative values in one channel and large positive values in other
177: 	// channels can result in a colour that appears darker and more saturated than
178: 	// desired after passing it through the inset matrix. For this reason, it is
179: 	// best to prevent negative input values.
180: 	// This is done before the Rec. 2020 transform to allow the Rec. 2020
181: 	// transform to be combined with the AgX inset matrix. This results in a loss
182: 	// of color information that could be correctly interpreted within the
183: 	// Rec. 2020 color space as positive RGB values, but is often not worth
184: 	// the performance cost of an additional matrix multiplication.
185: 	//
186: 	// Additionally, this AgX configuration was created subjectively based on
187: 	// output appearance in the Rec. 709 color gamut, so it is possible that these
188: 	// matrices will not perform well with non-Rec. 709 output (more testing with
189: 	// future wide-gamut displays is be needed).
190: 	// See this comment from the author on the decisions made to create the matrices:
191: 	// https://github.com/godotengine/godot-proposals/issues/12317#issuecomment-2835824250
192: 
193: 	// Combined Rec. 709 to Rec. 2020 and Blender AgX inset matrices:
194: 	const mat3 rec709_to_rec2020_agx_inset_matrix = mat3(
195: 			0.544814746488245, 0.140416948464053, 0.0888104196149096,
196: 			0.373787398372697, 0.754137554567394, 0.178871756420858,
197: 			0.0813978551390581, 0.105445496968552, 0.732317823964232);
198: 
199: 	// Combined inverse AgX outset matrix and Rec. 2020 to Rec. 709 matrices.
200: 	const mat3 agx_outset_rec2020_to_rec709_matrix = mat3(
201: 			1.96488741169489, -0.299313364904742, -0.164352742528393,
202: 			-0.855988495690215, 1.32639796461980, -0.238183969428088,
203: 			-0.108898916004672, -0.0270845997150571, 1.40253671195648);
204: 
205: 	const float output_max_value = 1.0; // SDR always has an output_max_value of 1.0
206: 
207: 	// Apply inset matrix.
208: 	color = rec709_to_rec2020_agx_inset_matrix * color;
209: 
210: 	// Use the allenwp tonemapping curve to match the Blender AgX curve while
211: 	// providing stability across all variable dyanimc range (SDR, HDR, EDR).
212: 	color = allenwp_curve(color);
213: 
214: 	// Clipping to output_max_value is required to address a cyan colour that occurs
215: 	// with very bright inputs.
216: 	color = min(vec3(output_max_value), color);
217: 
218: 	// Apply outset to make the result more chroma-laden and then go back to Rec. 709.
219: 	color = agx_outset_rec2020_to_rec709_matrix * color;
220: 
221: 	// Blender's lusRGB.compensate_low_side is too complex for this shader, so
222: 	// simply return the color, even if it has negative components. These negative
223: 	// components may be useful for subsequent color adjustments.
224: 	return color;
